// Stable keys (ADR-007 §1): « s_8f2c » for a section, « b_3a91 » for a block — generated once, they survive every reorder and
// anchor the audit. Generated by the composer, never by the reducer (which stays pure).
const alphabet = "0123456789abcdef";

/** A short random key with a prefix; `random` is injectable so a test is deterministic. */
export function newKey(prefix: "s" | "b", random: () => number = Math.random): string {
  let out = "";
  for (let i = 0; i < 6; i++) out += alphabet[Math.floor(random() * 16)];
  return `${prefix}_${out}`;
}
